// A fixed default port is a trap on a shared runner: a browser left behind by
// an interrupted run keeps listening, so the next run would either talk to a
// stale page target or fail the launch. Without an explicit --port we ask the
// kernel for a free one and never inherit somebody else's browser.
const DEBUG_PORT = args.includes('--port') ? Number(argValue('port', '9222')) : null;

