/** Ask the kernel for a free loopback port (we close it again immediately). */
function freePort() {
  return new Promise((resolve, reject) => {
    const probe = net.createServer();
    probe.once('error', reject);
    probe.listen(0, '127.0.0.1', () => {
      const { port } = probe.address();
      probe.close(() => resolve(port));
    });
  });
}

/** The `/json/version` payload of a browser that already serves `port`, else null. */
async function devtoolsInfo(port) {
  try {
    const res = await fetch(`http://127.0.0.1:${port}/json/version`, { signal: AbortSignal.timeout(2_000) });
    if (!res.ok) return null;
    return await res.json();
  } catch {
    return null;
  }
}

/**
 * Launch headless Chromium and wait for its DevTools endpoint.
 *
 * Measured 2026-10-19 on a cold runner: the first start needs well over the
 * former 30 s budget before `/json/version` answers, and the orphan browser of
 * the failed run kept the fixed port 9222, so every later run either hung on a
 * stale target or refused to start. Now: a free port per run, a 90 s budget, an
 * early exit is diagnosed instead of waited out, and one retry on a fresh port
 * covers a launch that dies for another reason.
 */
async function launchChrome() {
  const attempts = DEBUG_PORT === null ? 2 : 1;
  let lastError = null;
  for (let attempt = 0; attempt < attempts; attempt += 1) {
    const port = DEBUG_PORT ?? (await freePort());
    const existing = await devtoolsInfo(port);
    if (existing) {
      lastError = new Error(`port ${port} already serves a DevTools endpoint (${existing['Browser'] ?? 'unknown browser'})`);
      continue;
    }
    const userDataDir = path.join(os.tmpdir(), `kartenzeit-chrome-${process.pid}-${attempt}-${port}`);
    const chrome = spawn(
      CHROME,
      [
        '--headless=new',
        '--no-sandbox',
        '--disable-gpu',
        '--disable-dev-shm-usage',
        '--hide-scrollbars',
        '--window-size=1440,960',
        `--remote-debugging-port=${port}`,
        `--user-data-dir=${userDataDir}`,
        'about:blank',
      ],
      { stdio: ['ignore', 'pipe', 'pipe'] },
    );
    const stderr = [];
    chrome.stderr.on('data', (d) => stderr.push(d.toString()));
    chrome.once('exit', (code) => {
      lastError = new Error(`Chromium exited early (code ${code})\n${stderr.join('').slice(-600)}`);
    });

    const deadline = Date.now() + 90_000;
    let info = null;
    while (Date.now() < deadline) {
      if (chrome.exitCode !== null) break;
      info = await devtoolsInfo(port);
      if (info) break;
      await sleep(250);
    }
    if (info && chrome.exitCode === null) {
      const target = await openPageTarget(port);
      return { chrome, userDataDir, port, info, target, stderr };
    }
    if (info) {
      // The endpoint answered after the process was gone: nothing to drive.
      await openPageTarget(port).catch(() => {});
    }
    chrome.kill('SIGKILL');
    await rm(userDataDir, { recursive: true, force: true }).catch(() => {});
    if (attempt === attempts - 1) {
      throw new Error(`Chromium did not expose a usable DevTools endpoint on port ${port}: ${lastError?.message ?? 'timed out'}`);
    }
    console.log(`ℹ Chromium launch attempt ${attempt + 1} failed (${lastError?.message?.split('\n')[0] ?? 'timeout'}); retrying on a fresh port …`);
  }
  throw lastError ?? new Error('Chromium could not be started');
}

/** A page target's WebSocket (domains Page/Runtime/Network live there, not on the browser socket). */
async function openPageTarget(port) {
  for (const method of ['PUT', 'GET']) {
    try {
      const res = await fetch(`http://127.0.0.1:${port}/json/new?about:blank`, { method });
      if (res.ok) {
        const target = await res.json();
        if (target.webSocketDebuggerUrl) return target.webSocketDebuggerUrl;
      }
    } catch {
      /* try the next method */
    }
  }
  throw new Error('could not open a DevTools page target');
}

